        child: SingleChildScrollView(
          padding: const EdgeInsets.all(DesignTokens.spacingMd),
          child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                Expanded(
                  child: Text('Nova entrada', style: DesignTokens.textTitleLg),
                ),
                IconButton(
                  onPressed: () {
                    context.read<InsertionModalBloc>().add(const ModalClosed());
                    Navigator.of(context).pop();
                  },
                  icon: const Icon(Icons.close),
                ),
              ],
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            BlocBuilder<InsertionModalBloc, InsertionModalState>(
              builder: (context, state) {
                return Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    CaptureTabBar(
                      activeTab: _tabOf(state),
                      onTabSelected: (tab) =>
                          context.read<InsertionModalBloc>().add(TabSelected(tab)),
                    ),
                    const SizedBox(height: DesignTokens.spacingMd),
                    switch (state) {
                      InsertionModalTexto() ||
                      InsertionModalTextoSaving() ||
                      InsertionModalTextoFailure() => TextoTabView(state: state),
                      InsertionModalAudioPermissionDenied() ||
                      InsertionModalAudioRecording() ||
                      InsertionModalAudioSaving() ||
                      InsertionModalAudioFailure() => AudioTabView(state: state),
                      InsertionModalFotoCaptura() ||
                      InsertionModalFotoPermissionDenied() ||
                      InsertionModalFotoSaving() ||
                      InsertionModalFotoFailure() => FotoTabView(state: state),
                    },
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

