1	import 'dart:async';
2	
3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/capture/domain/entities/recognition_failure.dart';
5	import 'package:cerne/features/capture/domain/repositories/audio_capture_repository.dart';
6	import 'package:cerne/features/capture/domain/repositories/photo_capture_repository.dart';
7	import 'package:cerne/features/capture/domain/usecases/save_audio_entry_usecase.dart';
8	import 'package:cerne/features/capture/domain/usecases/save_photo_entry_usecase.dart';
9	import 'package:cerne/features/capture/domain/usecases/save_text_entry_usecase.dart';
10	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
11	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
12	import 'package:flutter_bloc/flutter_bloc.dart';
13	
14	const _offlineMessage = 'Sem conexão. Conecte-se à internet para salvar.';
15	const _noSpeechMessage = 'Não foi possível identificar fala no áudio.';
16	const _genericAudioMessage = 'Não foi possível processar o áudio.';
17	const _noTextMessage = 'Não foi possível identificar texto na imagem.';
18	
19	/// One screen-scoped bloc for the whole Insertion Modal
20	/// (contracts/insertion-modal-bloc.md) — created fresh by `BlocProvider`
21	/// every time `showModalBottomSheet` opens the modal, which is what makes
22	/// FR-002's "reset every tab... each time the modal is freshly opened" true
23	/// without an explicit reset event.
24	class InsertionModalBloc extends Bloc<InsertionModalEvent, InsertionModalState> {
25	  InsertionModalBloc({
26	    required this._saveTextEntryUseCase,
27	    required this._audioCaptureRepository,
28	    required this._saveAudioEntryUseCase,
29	    required this._photoCaptureRepository,
30	    required this._savePhotoEntryUseCase,
31	  }) : super(const InsertionModalTexto()) {
32	    on<TabSelected>(_onTabSelected);
33	    on<TextDraftChanged>(_onTextDraftChanged);
34	    on<SaveTextSubmitted>(_onSaveTextSubmitted);
35	    on<AudioTimerTicked>(_onAudioTimerTicked);
36	    on<AudioStopRequested>(_onAudioStopRequested);
37	    on<PhotoSourceSelected>(_onPhotoSourceSelected);
38	    on<RetryRequested>(_onRetryRequested);
39	    on<ModalClosed>(_onModalClosed);
40	  }
41	
42	  final SaveTextEntryUseCase _saveTextEntryUseCase;
43	  final AudioCaptureRepository _audioCaptureRepository;
44	  final SaveAudioEntryUseCase _saveAudioEntryUseCase;
45	  final PhotoCaptureRepository _photoCaptureRepository;
46	  final SavePhotoEntryUseCase _savePhotoEntryUseCase;
47	
48	  final _closeController = StreamController<void>.broadcast();
49	
50	  /// A one-shot side effect, not a state (FR-011, contracts/
51	  /// insertion-modal-bloc.md) — `InsertionModalPage` listens to this to pop
52	  /// the sheet. There is nothing to render for "success", so it never
53	  /// becomes a dedicated `InsertionModalState` case.
54	  Stream<void> get closeRequests => _closeController.stream;
55	
56	  String _textDraft = '';
57	  String? _pendingAudioPath;
58	  String? _pendingImagePath;
59	  Timer? _audioTicker;
60	
61	  /// Guards against discarding the same recording twice when both the
62	  /// explicit `ModalClosed` handler and `close()`'s disposal-time fallback
63	  /// (T073, for the swipe-down/tap-outside dismissal that bypasses
64	  /// `ModalClosed`) would otherwise race on the same still-recording state.
65	  bool _recordingDiscarded = false;
66	
67	  Future<void> _onTabSelected(
68	    TabSelected event,
69	    Emitter<InsertionModalState> emit,
70	  ) async {
71	    if (state is InsertionModalAudioRecording) {
72	      // Switching away mid-recording discards it (Edge Cases) — nothing
73	      // from an abandoned capture may survive (FR-008).
74	      _audioCaptureRepository.discard();
75	      _recordingDiscarded = true;
76	      _stopAudioTicker();
77	      _pendingAudioPath = null;
78	    }
79	
80	    switch (event.tab) {
81	      case CaptureTab.texto:
82	        emit(InsertionModalTexto(text: _textDraft));
83	      case CaptureTab.audio:
84	        await _startAudioTab(emit);
85	      case CaptureTab.foto:
86	        emit(const InsertionModalFotoCaptura());
87	    }
88	  }
89	
90	  Future<void> _startAudioTab(Emitter<InsertionModalState> emit) async {
91	    final hasPermission = await _audioCaptureRepository.hasPermission();
92	    if (!hasPermission) {
93	      emit(const InsertionModalAudioPermissionDenied());
94	      return;
95	    }
96	    await _audioCaptureRepository.start();
97	    _recordingDiscarded = false;
98	    emit(const InsertionModalAudioRecording(elapsed: Duration.zero));
99	    _startAudioTicker();
100	  }
101	
102	  void _startAudioTicker() {
103	    _audioTicker?.cancel();
104	    _audioTicker = Timer.periodic(
105	      const Duration(seconds: 1),
106	      (_) => add(const AudioTimerTicked()),
107	    );
108	  }
109	
110	  void _stopAudioTicker() {
111	    _audioTicker?.cancel();
112	    _audioTicker = null;
113	  }
114	
115	  void _onTextDraftChanged(
116	    TextDraftChanged event,
117	    Emitter<InsertionModalState> emit,
118	  ) {
119	    _textDraft = event.text;
120	    emit(InsertionModalTexto(text: event.text));
121	  }
122	
123	  void _onAudioTimerTicked(
124	    AudioTimerTicked event,
125	    Emitter<InsertionModalState> emit,
126	  ) {
127	    final current = state;
128	    if (current is InsertionModalAudioRecording) {
129	      emit(
130	        InsertionModalAudioRecording(
131	          elapsed: current.elapsed + const Duration(seconds: 1),
132	        ),
133	      );
134	    }
135	  }
136	
137	  Future<void> _onSaveTextSubmitted(
138	    SaveTextSubmitted event,
139	    Emitter<InsertionModalState> emit,
140	  ) async {
141	    final current = state;
142	    final text = switch (current) {
143	      InsertionModalTexto(text: final t) => t,
144	      InsertionModalTextoFailure(text: final t) => t,
145	      _ => null,
146	    };
147	    if (text == null || text.trim().isEmpty) return;
148	
149	    emit(InsertionModalTextoSaving(text));
150	    final result = await _saveTextEntryUseCase(text);
151	    result.match(
152	      (failure) => emit(
153	        InsertionModalTextoFailure(text: text, message: failure.message),
154	      ),
155	      (entry) => _completeSave(),
156	    );
157	  }
158	
159	  Future<void> _onAudioStopRequested(
160	    AudioStopRequested event,
161	    Emitter<InsertionModalState> emit,
162	  ) async {
163	    if (state is! InsertionModalAudioRecording) return;
164	
165	    _stopAudioTicker();
166	    final path = await _audioCaptureRepository.stop();
167	    _pendingAudioPath = path;
168	    emit(const InsertionModalAudioSaving());
169	    await _saveAudio(path, emit);
170	  }
171	
172	  Future<void> _saveAudio(
173	    String audioFilePath,
174	    Emitter<InsertionModalState> emit,
175	  ) async {
176	    final result = await _saveAudioEntryUseCase(audioFilePath);
177	    result.match(
178	      (failure) => emit(InsertionModalAudioFailure(_audioFailureMessage(failure))),
179	      (entry) {
180	        _pendingAudioPath = null;
181	        _completeSave();
182	      },
183	    );
184	  }
185	
186	  String _audioFailureMessage(SaveAudioFailure failure) => switch (failure) {
187	    SaveAudioOffline() => _offlineMessage,
188	    SaveAudioRecognitionFailed(:final recognitionFailure) => switch (recognitionFailure) {
189	      EmptyRecognitionResult() => _noSpeechMessage,
190	      TranscriptionError() => _genericAudioMessage,
191	    },
192	    SaveAudioEntryCreationFailed(failure: final f) => f.message,
193	  };
194	
195	  Future<void> _onPhotoSourceSelected(
196	    PhotoSourceSelected event,
197	    Emitter<InsertionModalState> emit,
198	  ) async {
199	    if (state is InsertionModalFotoSaving) return;
200	
201	    String? path;
202	    try {
203	      path = await _photoCaptureRepository.pickImage(event.source);
204	    } catch (_) {
205	      emit(const InsertionModalFotoPermissionDenied());
206	      return;
207	    }
208	
209	    if (path == null) {
210	      emit(const InsertionModalFotoCaptura());
211	      return;
212	    }
213	
214	    _pendingImagePath = path;
215	    emit(const InsertionModalFotoSaving());
216	    await _savePhoto(path, emit);
217	  }
218	
219	  Future<void> _savePhoto(
220	    String imageFilePath,
221	    Emitter<InsertionModalState> emit,
222	  ) async {
223	    final result = await _savePhotoEntryUseCase(imageFilePath);
224	    result.match(
225	      (failure) => emit(InsertionModalFotoFailure(_photoFailureMessage(failure))),
226	      (entry) {
227	        _pendingImagePath = null;
228	        _completeSave();
