8	/// Reads `AudioCaptureRepository.amplitudeStream` directly via `get_it` —
9	/// the one sanctioned bypass of "always through the bloc" for this unit,
10	/// since the amplitude signal is too high-frequency to belong in bloc event
11	/// history (contracts/audio-capture-repository.md).
12	class AudioWaveform extends StatelessWidget {
13	  const AudioWaveform({super.key});
14	
15	  @override
16	  Widget build(BuildContext context) {
17	    final repository = getIt<AudioCaptureRepository>();
18	    return StreamBuilder<double>(
19	      stream: repository.amplitudeStream,
20	      builder: (context, snapshot) {
21	        final amplitudeDbfs = snapshot.data ?? -45.0;
22	        final normalized = ((amplitudeDbfs + 60) / 60).clamp(0.0, 1.0);
23	        return Row(
24	          mainAxisAlignment: MainAxisAlignment.center,
25	          children: List.generate(
26	            _barCount,
27	            (index) => Padding(
28	              padding: const EdgeInsets.symmetric(
29	                horizontal: DesignTokens.spacingXs,
30	              ),
31	              child: Container(
32	                width: DesignTokens.spacingXs,
33	                height:
34	                    DesignTokens.spacingSm + normalized * DesignTokens.spacingXl,
35	                decoration: BoxDecoration(
36	                  color: DesignTokens.colorPrimary,
37	                  borderRadius: BorderRadius.circular(DesignTokens.radiusSm),
38	                ),
39	              ),
40	            ),
41	          ),
42	        );
43	      },
44	    );
45	  }
46	}
